<?php require_once 'functions.php'; require_login(); if(!is_admin()){http_response_code(403);page_header('Access denied');echo '<div class="empty">Administrator access only.</div>';page_footer();exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['claim_action'])){$claimId=(int)($_POST['claim_id']??0);$itemId=(int)($_POST['item_id']??0);$action=$_POST['claim_action'];if(in_array($action,['approved','rejected'],true)){$st=$pdo->prepare('UPDATE claims SET claim_status=? WHERE id=?');$st->execute([$action,$claimId]);if($action==='approved'){$pdo->prepare("UPDATE items SET status='returned' WHERE id=?")->execute([$itemId]);$pdo->prepare("UPDATE claims SET claim_status='rejected' WHERE item_id=? AND id<>? AND claim_status='pending'")->execute([$itemId,$claimId]);}flash('Claim status updated.');}header('Location: admin.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['item_action'])){$action=$_POST['item_action'];$id=(int)($_POST['item_id']??0);if(in_array($action,['active','closed','returned'],true)){$st=$pdo->prepare('UPDATE items SET status=? WHERE id=?');$st->execute([$action,$id]);flash('Item status updated.');}header('Location: admin.php');exit;}
$items=$pdo->query('SELECT i.*,u.full_name FROM items i JOIN users u ON u.id=i.user_id ORDER BY i.created_at DESC')->fetchAll();$claims=$pdo->query('SELECT c.*,i.title item_title,i.id item_id,u.full_name claimant,u.email FROM claims c JOIN items i ON i.id=c.item_id JOIN users u ON u.id=c.claimant_user_id ORDER BY (c.claim_status="pending") DESC,c.created_at DESC')->fetchAll();$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM items) items,(SELECT COUNT(*) FROM claims WHERE claim_status='pending') pending")->fetch();page_header('Admin dashboard'); ?><p class="eyebrow">SYSTEM MANAGEMENT</p><h1>Admin dashboard</h1><p class="muted">Review reports and manage item claims.</p><section class="stats admin-stats"><div><strong><?=(int)$stats['users']?></strong><span>Users</span></div><div><strong><?=(int)$stats['items']?></strong><span>Reports</span></div><div><strong><?=(int)$stats['pending']?></strong><span>Pending claims</span></div></section><section class="panel table-wrap"><h2>All item reports</h2><table><thead><tr><th>Item</th><th>Reporter</th><th>Type</th><th>Status</th><th>Update status</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><a class="text-link" href="item.php?id=<?=(int)$i['id']?>"><?=e($i['title'])?></a></td><td><?=e($i['full_name'])?></td><td><?=e($i['item_type'])?></td><td><?=e($i['status'])?></td><td><form class="inline-form" method="post"><input type="hidden" name="item_id" value="<?=(int)$i['id']?>"><select name="item_action"><option value="active">Active</option><option value="closed">Closed</option><option value="returned">Returned</option></select><button class="button small-button">Save</button></form></td></tr><?php endforeach; ?></tbody></table></section><section class="panel table-wrap"><h2>Claims review</h2><table><thead><tr><th>Item</th><th>Claimant</th><th>Message</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($claims as $c): ?><tr><td><a class="text-link" href="item.php?id=<?=(int)$c['item_id']?>"><?=e($c['item_title'])?></a></td><td><?=e($c['claimant'])?><div class="muted small"><?=e($c['email'])?></div></td><td><?=e($c['claim_message'])?></td><td><?=e($c['claim_status'])?></td><td><?php if($c['claim_status']==='pending'): ?><form class="inline-form" method="post"><input type="hidden" name="claim_id" value="<?=(int)$c['id']?>"><input type="hidden" name="item_id" value="<?=(int)$c['item_id']?>"><button class="button small-button" name="claim_action" value="approved">Approve</button><button class="button danger small-button" name="claim_action" value="rejected">Reject</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$claims): ?><tr><td colspan="5">No claims submitted yet.</td></tr><?php endif; ?></tbody></table></section><?php page_footer(); ?>
